import React, { useState } from 'react';

export default function ContactForm() {
  const [form, setForm] = useState({ isim: '', email: '', mesaj: '' });
  const [ok, setOk] = useState(false);
  if (ok) return <div className="text-center text-white py-20"><p className="text-5xl mb-4">✅</p><h2 className="text-2xl font-bold">Gönderildi!</h2></div>;
  return (
    <form onSubmit={e => { e.preventDefault(); setOk(true); }} className="w-full max-w-lg bg-gray-900 border border-gray-800 rounded-2xl p-8 space-y-5 mx-auto">
      <h2 className="text-2xl font-bold text-white">İletişim</h2>
      <input value={form.isim} onChange={e=>setForm({...form,isim:e.target.value})} placeholder="İsim" className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-white outline-none" />
      <input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="E-posta" className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-white outline-none" />
      <textarea value={form.mesaj} onChange={e=>setForm({...form,mesaj:e.target.value})} rows={4} placeholder="Mesaj" className="w-full bg-gray-800 border border-gray-700 rounded-xl px-4 py-2.5 text-white outline-none resize-none" />
      <button className="w-full bg-blue-600 text-white py-3 rounded-xl font-medium">Gönder</button>
    </form>
  );
}
